"""Read-only access to the case files. No SQL generated by the model."""

import csv
import json
import re
import sqlite3
import unicodedata
from pathlib import Path

from pypdf import PdfReader


def normalize(value: str) -> str:
    value = unicodedata.normalize("NFKD", str(value)).casefold()
    return "".join(c for c in value if not unicodedata.combining(c))


def money(value: float) -> str:
    return f"R$ {value:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


class Store:
    def __init__(self, data_dir: str | Path):
        self.data_dir = Path(data_dir)
        self.tables = {}
        for name in ("products", "categories", "promotions", "orders", "customers"):
            matches = list(self.data_dir.glob(f"*{name}.csv"))
            if len(matches) != 1:
                raise FileNotFoundError(f"Expected one *{name}.csv in {self.data_dir}")
            with matches[0].open(newline="", encoding="utf-8-sig") as f:
                self.tables[name] = list(csv.DictReader(f))
        policy = list(self.data_dir.glob("*.pdf"))
        if len(policy) != 1:
            raise FileNotFoundError(f"Expected one policy PDF in {self.data_dir}")
        self.policy_pages = [page.extract_text() or "" for page in PdfReader(policy[0]).pages]
        self.categories = {r["category_id"]: r["name"] for r in self.tables["categories"]}
        self.promotions = {}
        for row in self.tables["promotions"]:
            if row["is_active"].strip().lower() in ("1", "true", "yes"):
                self.promotions.setdefault(row["product_id"], []).append(row)
        self._build_db()

    def _build_db(self) -> None:
        """Load a typed, relational snapshot; source files remain untouched."""
        self.db = sqlite3.connect(":memory:", check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.executescript("""
            PRAGMA foreign_keys = ON;
            CREATE TABLE categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
            CREATE TABLE products (id INTEGER PRIMARY KEY, name TEXT NOT NULL,
                description TEXT NOT NULL, category_id INTEGER NOT NULL REFERENCES categories(id),
                price_brl REAL NOT NULL, stock_quantity INTEGER NOT NULL, status TEXT NOT NULL);
            CREATE TABLE promotions (product_id INTEGER NOT NULL REFERENCES products(id),
                discount_percent REAL NOT NULL);
            CREATE TABLE customers (id INTEGER PRIMARY KEY, email TEXT NOT NULL);
            CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id),
                status TEXT NOT NULL, order_date TEXT, estimated_delivery TEXT, tracking_code TEXT);
            CREATE INDEX idx_orders_customer ON orders(customer_id);
            CREATE INDEX idx_promotions_product ON promotions(product_id);
        """)
        with self.db:
            self.db.executemany("INSERT INTO categories VALUES (?, ?)",
                ((int(cid), name) for cid, name in self.categories.items()))
            self.db.executemany("INSERT INTO products VALUES (?, ?, ?, ?, ?, ?, ?)",
                ((int(r["product_id"]), r["name"], r["description"], int(r["category_id"]),
                  float(r["price_brl"]), int(r["stock_quantity"]), r["status"])
                 for r in self.tables["products"]))
            self.db.executemany("INSERT INTO promotions VALUES (?, ?)",
                ((int(pid), float(r["discount_percent"]))
                 for pid, rows in self.promotions.items() for r in rows))
            self.db.executemany("INSERT INTO customers VALUES (?, ?)",
                ((int(r["customer_id"]), r["email"]) for r in self.tables["customers"]))
            self.db.executemany("INSERT INTO orders VALUES (?, ?, ?, ?, ?, ?)",
                ((int(r["order_id"]), int(r["customer_id"]), r["status"], r["order_date"],
                  r["estimated_delivery"], r["tracking_code"]) for r in self.tables["orders"]))

    def search_products(self, query: str = "", max_price: float | None = None, limit: int = 8,
                        in_stock_only: bool = False) -> dict:
        if max_price is not None and (max_price < 0 or max_price > 1_000_000):
            return {"error": "Invalid price limit"}
        words = [w for w in re.findall(r"\w+", normalize(query)) if len(w) > 1 and w not in ("de", "da", "do")]
        category_query = normalize(query).strip()
        aliases = {"violao": "violoes", "guitarra": "guitarras", "baixo": "baixos",
                   "bateria": "baterias", "teclado": "teclados", "ukulele": "ukuleles"}
        canonical_category = aliases.get(category_query, category_query)
        category_ids = {cid for cid, name in self.categories.items()
                        if canonical_category == normalize(name)}
        found = []
        rows = self.db.execute("""
            SELECT p.*, c.name AS category, COALESCE(MAX(m.discount_percent), 0) AS discount
            FROM products p JOIN categories c ON c.id = p.category_id
            LEFT JOIN promotions m ON m.product_id = p.id
            WHERE p.status = 'active' AND (? = 0 OR p.stock_quantity > 0)
            GROUP BY p.id
        """, (int(in_stock_only),)).fetchall()
        for row in rows:
            if row["status"].lower() != "active":
                continue
            haystack = normalize(" ".join((row["name"], row["description"], row["category"])))
            if category_ids and str(row["category_id"]) not in category_ids:
                continue
            if not category_ids and words and not all(word in haystack for word in words):
                continue
            original = row["price_brl"]
            discount = row["discount"]
            current = round(original * (1 - discount / 100), 2)
            if max_price is not None and current > max_price:
                continue
            found.append({"id": str(row["id"]), "name": row["name"],
                          "category": row["category"],
                          "price_brl": money(current), "original_price_brl": money(original) if discount else None,
                          "discount_percent": discount or None,
                          "stock_quantity": int(row["stock_quantity"])})
        found.sort(key=lambda x: (0 if normalize(x["name"]) == normalize(query) else 1,
                                  0 if normalize(query) and normalize(query) in normalize(x["name"]) else 1,
                                  normalize(x["name"]), x["id"]))
        return {"results": found[:max(1, min(limit, 12))], "total_matches": len(found),
                "source": "CSV snapshot loaded into SQLite at startup"}

    def get_order(self, order_id: str, email: str) -> dict:
        # Matching both identifiers reduces accidental disclosure in a text-only prototype.
        if not order_id.isdigit() or not email.strip():
            return {"error": "Ask for order number and purchase email."}
        order = self.db.execute("""SELECT o.* FROM orders o JOIN customers c ON c.id = o.customer_id
            WHERE o.id = ? AND lower(trim(c.email)) = lower(trim(?))""", (int(order_id), email)).fetchone()
        if order is None:
            return {"error": "Order not found or identity not verified."}
        return {"order_id": order_id, "status": order["status"],
                "order_date": order["order_date"], "estimated_delivery": order["estimated_delivery"],
                "tracking_code": order["tracking_code"] or None,
                "source": "orders CSV snapshot; no live carrier tracking"}

    def get_policy(self, topic: str) -> dict:
        if not topic.strip():
            return {"error": "Specify a policy topic."}
        words = [w for w in re.findall(r"\w+", normalize(topic)) if len(w) > 3]
        scored = []
        for i, page in enumerate(self.policy_pages, 1):
            paragraphs = [" ".join(p.split()) for p in page.split("\n\n") if p.strip()]
            for paragraph in paragraphs:
                score = sum(normalize(paragraph).count(w) for w in words)
                if score:
                    scored.append((score, i, paragraph))
        scored.sort(key=lambda x: x[0], reverse=True)
        return {"matches": [{"page": i, "text": p[:1600]} for _, i, p in scored[:4]],
                "source": "store policy PDF, version 2.1 (June 2025)"}


def run_tool(store: Store, name: str, arguments: str) -> str:
    try:
        args = json.loads(arguments)
        if name == "search_products":
            result = store.search_products(**args)
        elif name == "get_order":
            result = store.get_order(**args)
        elif name == "get_policy":
            result = store.get_policy(**args)
        else:
            result = {"error": "Unknown tool"}
        return json.dumps(result, ensure_ascii=False)
    except (TypeError, ValueError) as exc:
        return json.dumps({"error": f"Invalid arguments: {exc}"})

